import pulp

# ----------------------------------------------------------------------
# Data
# ----------------------------------------------------------------------
plants = [
    "Alpha", "Beta", "Gamma", "Delta", "Epsilon",
    "Zeta", "Eta", "Theta", "Iota"
]

substations = [
    "Delta", "Epsilon", "Zeta", "Eta", "Theta",
    "Iota", "Kappa", "Lambda", "Mu"
]

# Plant generation capacities (MW)
