    },
    "Epsilon": {
        "Delta": 31, "Epsilon": 11, "Zeta": 71, "Eta": 72,
        "Theta": 67, "Iota": 14, "Kappa": 34, "Lambda": 21, "Mu": 55
    },
    "Zeta": {
        "Delta": 93, "Epsilon": 89, "Zeta": 63, "Eta": 13,
        "Theta": 36, "Iota": 34, "Kappa": 20, "Lambda": 24, "Mu": 60
    },
    "Eta": {
        "Delta": 91, "Epsilon": 67, "Zeta": 58, "Eta": 37,
        "Theta": 82, "Iota": 29, "Kappa": 75, "Lambda": 9, "Mu": 75
    },
    "Theta": {
        "Delta": 94, "Epsilon": 90, "Zeta": 54, "Eta": 24,
        "Theta": 94, "Iota": 68, "Kappa": 99, "Lambda": 78, "Mu": 22
