        "Delta": 11, "Epsilon": 44, "Zeta": 54, "Eta": 79,
        "Theta": 66, "Iota": 90, "Kappa": 63, "Lambda": 81, "Mu": 100
    }
}

# Transmission costs (cost per MW)
transmission_cost = {
    "Alpha": {
        "Delta": 6, "Epsilon": 4, "Zeta": 3, "Eta": 4,
        "Theta": 3, "Iota": 1, "Kappa": 10, "Lambda": 1, "Mu": 8
    },
    "Beta": {
        "Delta": 8, "Epsilon": 9, "Zeta": 9, "Eta": 4,
        "Theta": 7, "Iota": 4, "Kappa": 4, "Lambda": 10, "Mu": 2
    },
    "Gamma": {
        "Delta": 6, "Epsilon": 3, "Zeta": 5, "Eta": 2,
        "Theta": 8, "Iota": 8, "Kappa": 4, "Lambda": 8, "Mu": 5
    },
    "Delta": {
        "Delta": 8, "Epsilon": 4, "Zeta": 8, "Eta": 3,
        "Theta": 10, "Iota": 4, "Kappa": 10, "Lambda": 7, "Mu": 6
    },
    "Epsilon": {
        "Delta": 7, "Epsilon": 5, "Zeta": 7, "Eta": 3,
        "Theta": 3, "Iota": 10, "Kappa": 9, "Lambda": 8, "Mu": 2
    },
    "Zeta": {
        "Delta": 4, "Epsilon": 10, "Zeta": 6, "Eta": 10,
