        "Delta": 8, "Epsilon": 6, "Zeta": 1, "Eta": 9,
        "Theta": 7, "Iota": 2, "Kappa": 7, "Lambda": 5, "Mu": 1
    }
}

# ----------------------------------------------------------------------
# Model
# ----------------------------------------------------------------------
model = pulp.LpProblem("Power_Distribution", pulp.LpMinimize)

# Decision variables: flow from plant p to substation s (MW)
x = {}
for p in plants:
    for s in substations:
        var_name = f"x_{p}_{s}"
        # No lower bound here; non‑negativity will be enforced by R4 constraints
        x[(p, s)] = pulp.LpVariable(var_name, lowBound=None, cat='Continuous')

# ----------------------------------------------------------------------
# Objective: minimize total transmission cost
# ----------------------------------------------------------------------
model += pulp.lpSum(
    transmission_cost[p][s] * x[(p, s)] for p in plants for s in substations
), "Total_Transmission_Cost"

# ----------------------------------------------------------------------
# Requirement R1: meet each substation's demand exactly
# ----------------------------------------------------------------------
for s in substations:
    model += (
        pulp.lpSum(x[(p, s)] for p in plants) == substation_demand[s],
        f"R1_{s}"
    )

# ----------------------------------------------------------------------
# Requirement R2: plant generation capacity (upper bound)
# ----------------------------------------------------------------------
for p in plants:
    model += (
        pulp.lpSum(x[(p, s)] for s in substations) <= plant_capacity[p],
        f"R2_{p}"
    )

# ----------------------------------------------------------------------
# Requirement R3: transmission line capacity (upper bound)
# ----------------------------------------------------------------------
for p in plants:
    for s in substations:
        model += (
            x[(p, s)] <= line_capacity[p][s],
            f"R3_{p}_{s}"
        )

# ----------------------------------------------------------------------
# Requirement R4: non‑negative flows
# ----------------------------------------------------------------------
for p in plants:
    for s in substations:
        model += (
            x[(p, s)] >= 0,
            f"R4_{p}_{s}"
        )

# ----------------------------------------------------------------------
# Solve
# ----------------------------------------------------------------------
solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

# ----------------------------------------------------------------------
# Output
# ----------------------------------------------------------------------
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total cost = {pulp.value(model.objective):.2f}")

print("\nFlows (MW):")
for p in plants:
    for s in substations:
        flow = x[(p, s)].varValue
        if flow is not None and flow > 1e-6:  # show only positive flows
            print(f"  {p} -> {s}: {flow:.2f}")
